from datetime import datetime
import uuid
from flask import Blueprint, request, jsonify, current_app
from werkzeug.exceptions import Unauthorized, BadRequest
import jwt
from functools import wraps

maddie_api = Blueprint('maddie_v2', __name__)

def require_jwt(scopes):
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            auth_header = request.headers.get('Authorization')
            if not auth_header or not auth_header.startswith('Bearer '):
                raise Unauthorized(description="Missing or invalid authorization header")

            token = auth_header[7:]
            try:
                payload = jwt.decode(token, current_app.config['JWT_SECRET'], algorithms=['HS256'])
            except jwt.ExpiredSignatureError:
                raise Unauthorized(description="Token expired")
            except jwt.InvalidTokenError:
                raise Unauthorized(description="Invalid token")

            if not set(scopes).issubset(set(payload.get('scopes', []))):
                raise Unauthorized(description="Insufficient scopes")

            request.user = payload
            return f(*args, **kwargs)
        return wrapped
    return decorator

